RECRUITMENT_JS = 'const RecruitmentDashboard=(()=>{\n const sections=[[\'new\',\'New this scan\'],[\'still\',\'Still available\'],[\'joined_my\',\'Joined War Haven\'],[\'no_longer\',\'No longer available\']];\n const labels={NEW:\'New this scan\',STILL_CLANLESS:\'Still clanless\',JOINED_MY_CLAN:\'Joined War Haven\',JOINED_OTHER_CLAN:\'Joined another clan\',BELOW_FILTERS:\'Outside filters\',ARCHIVED:\'Archived\',COOLDOWN_CLANLESS:\'Duplicate cooldown\',VERIFY_ERROR:\'Needs verification\'};\n let model=null,observer=null,filters={search:\'\',section:\'all\',hall:0,stars:0,league:0,sort:\'newest\'};\n function legacy(report){\n  // Read data from older saved reports; none of their markup or scripts enters the dashboard.\n  const doc=new DOMParser().parseFromString(report.html||\'\',\'text/html\'),groups=Object.fromEntries(sections.map(([key])=>[key,[]]));\n  for(const card of doc.querySelectorAll(\'.candidate\')){\n   const d=card.dataset,read=s=>card.querySelector(s)?.textContent.trim()||\'\',times=[...card.querySelectorAll(\'.timing .local-time\')].map(t=>t.dataset.iso||\'\');\n   const badges=[...card.querySelectorAll(\'.badges .badge\')].map(t=>t.textContent.trim());\n   const row={name:read(\'h3\'),tag:read(\'.tag\'),townHallLevel:Number(d.th),warStars:Number(d.war),bestTrophies:Number(d.best),trophies:Number(d.trophies),expLevel:Number(d.xp),leagueTierScore:Number(d.league),leagueTierName:badges[2],freshness:badges[0],lifecycle:badges[1],observationWindowSeconds:Number(d.window),detectedAt:d.detected,previousRosterAt:times[0],firstClanlessVerifiedAt:times[2],lastVerifiedAt:times[3],sourceClan:read(\'.source strong\'),leftWithin:read(\'.timing\').match(/Leave window:\\s*≤?\\s*([^]*?)First verified/)?.[1]?.trim()||\'unknown\',statusText:read(\'.gone,.joined-note\')};\n   row.profileLink=card.querySelector(\'a.open\')?.getAttribute(\'href\');(groups[d.section]||[]).push(row);\n  }\n  return {groups,turnover:[...doc.querySelectorAll(\'tbody tr\')].map(tr=>({cells:[...tr.children].map(td=>td.textContent.trim())})),updatedAt:report.updatedAt};\n }\n function matches(row,section){\n  const q=filters.search.toLowerCase().trim();\n  return (!q||[row.name,row.tag,row.sourceClan,row.sourceClanTag,row.currentClan,row.leagueTierName].join(\' \').toLowerCase().includes(q))&&(filters.section===\'all\'||section===filters.section)&&(row.townHallLevel||0)>=filters.hall&&(row.warStars||0)>=filters.stars&&(row.leagueTierScore||0)>=filters.league;\n }\n function compare(a,b){\n  const number=k=>(Number(b[k])||0)-(Number(a[k])||0);\n  if(filters.sort===\'hall\')return number(\'townHallLevel\');if(filters.sort===\'stars\')return number(\'warStars\');if(filters.sort===\'best\')return number(\'bestTrophies\');\n  if(filters.sort===\'window\')return (Number(a.observationWindowSeconds)||Number.MAX_SAFE_INTEGER)-(Number(b.observationWindowSeconds)||Number.MAX_SAFE_INTEGER);\n  return (Date.parse(b.detectedAt)||0)-(Date.parse(a.detectedAt)||0);\n }\n function candidate(row,section){\n  const time=(label,value)=>`<div><dt>${label}</dt><dd>${esc(date(value))}</dd></div>`,available=[\'new\',\'still\'].includes(section);\n  const tag=WarTracker.tag(row.tag),href=tag&&/^#[0289PYLQGRJCUV]+$/.test(tag)?\'https://link.clashofclans.com/en/?action=OpenPlayerProfile&tag=\'+encodeURIComponent(tag):null;\n  const state=labels[row.lifecycle]||row.lifecycle||\'\';\n  const status=section===\'joined_my\'?`Currently in ${row.currentClan||data.clanName||\'your clan\'}.`:row.lifecycle===\'JOINED_OTHER_CLAN\'?`Joined ${row.currentClan||\'another clan\'}.`:row.statusText||(!available?state:\'\');\n  return `<article class="panel recruit-card"><div class="recruit-identity"><div><h3 class="player-name-with-hall">${townHallIcon(row.townHallLevel)}<span>${esc(row.name||\'Unknown player\')}</span></h3><span class="tag">${esc(row.tag)}</span></div><span class="pill ${available?\'recruit-available\':\'\'}">${available?\'Available\':section===\'joined_my\'?\'Joined\':\'Unavailable\'}</span></div><div class="recruit-badges"><span>${esc(row.freshness||state)}</span><span>${esc(row.leagueTierName||\'League unknown\')}</span><span>TH ${formatNumber(row.townHallLevel)}</span></div><div class="recruit-metrics">${[[\'War stars\',row.warStars],[\'Best trophies\',row.bestTrophies],[\'Trophies\',row.trophies],[\'XP\',row.expLevel]].map(([label,value])=>`<div><strong>${formatNumber(value)}</strong><small>${label}</small></div>`).join(\'\')}</div><p class="recruit-source">Former clan <b>${esc(row.sourceClan||\'Unknown\')}</b>${row.sourceClanTag?` <span class="tag">${esc(row.sourceClanTag)}</span>`:\'\'}</p>${status?`<p class="small muted">${esc(status)}</p>`:\'\'}<details class="recruit-history"><summary>Verification &amp; departure history</summary><dl>${time(\'Last seen in clan\',row.previousRosterAt)}${time(\'Departure detected\',row.detectedAt)}<div><dt>Observed leave window</dt><dd>${esc(row.leftWithin||\'Unknown\')}</dd></div>${time(\'First verified clanless\',row.firstClanlessVerifiedAt)}${time(\'Latest profile check\',row.lastVerifiedAt)}${row.joinedMyClanAt?time(\'First joined our clan\',row.joinedMyClanAt):\'\'}</dl></details>${href?`<a class="recruit-open" href="${esc(href)}" target="_blank" rel="noopener noreferrer">Open in Clash ${icon(\'chevron\')}</a>`:\'\'}</article>`;\n }\n function reveal(){\n  observer?.disconnect();\n  if(!(\'IntersectionObserver\'in window)||window.matchMedia(\'(prefers-reduced-motion: reduce)\').matches)return;\n  observer=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){entry.target.classList.remove(\'recruit-scroll-pending\');observer.unobserve(entry.target);}},{threshold:.08,rootMargin:\'0px 0px -16px 0px\'});\n  $(\'recruitment-results\').querySelectorAll(\'.recruit-card\').forEach((card,index)=>{card.style.setProperty(\'--recruit-delay\',Math.min(index%3,2)*55+\'ms\');card.classList.add(\'recruit-scroll-pending\');observer.observe(card);});\n }\n function renderResults(){\n  let total=0;\n  $(\'recruitment-results\').innerHTML=sections.filter(([key])=>filters.section===\'all\'||filters.section===key).map(([key,label])=>{\n   const shown=(model.groups[key]||[]).filter(row=>matches(row,key)).sort(compare);total+=shown.length;\n   const content=`<div class="recruit-grid">${shown.map(row=>candidate(row,key)).join(\'\')||\'<p class="small muted recruit-empty">No candidates match these filters.</p>\'}</div>`;\n   return [\'joined_my\',\'no_longer\'].includes(key)?`<details class="recruit-section" ${filters.section===key?\'open\':\'\'}><summary>${label}<span class="pill">${shown.length}</span></summary>${content}</details>`:`<section class="recruit-section"><div class="section-heading"><h2>${label}</h2><span class="pill">${shown.length}</span></div>${content}</section>`;\n  }).join(\'\');\n  $(\'recruitment-count\').textContent=total+\' matching player\'+(total===1?\'\':\'s\');reveal();\n }\n function turnover(){\n  const list=model.turnover||[];\n  if(!list.length)return \'\';\n  return `<details class="panel recruit-turnover"><summary>Clan turnover <span class="small muted">${list.length} clans</span></summary><div class="table-wrap"><table><thead><tr>${[\'Clan\',\'Pool\',\'Leavers\',\'Qualifying\',\'Turnover\',\'Value\'].map(t=>`<th>${t}</th>`).join(\'\')}</tr></thead><tbody>${list.map(r=>`<tr>${(r.cells||[r.clanName+\' \'+r.clanTag,r.bucket,formatNumber(r.departuresDetected),formatNumber(r.qualifyingClanlessDepartures),formatNumber(r.turnoverRatePercent)+\'%\',r.recruitingValue]).map(v=>`<td>${esc(v)}</td>`).join(\'\')}</tr>`).join(\'\')}</tbody></table></div></details>`;\n }\n function open(){\n  const available=Boolean(recruiterReport.groups||recruiterReport.html),summary=data.recruiterSummary||{},failure=data.recruiterStatus?.ok===false;\n  $(\'recruiter-empty\').classList.toggle(\'hidden\',available);$(\'recruitment-content\').classList.toggle(\'hidden\',!available);\n  $(\'recruiter-status\').textContent=(available?\'Last scan \'+date(recruiterReport.updatedAt)+(summary.scannedClans?\' · \'+formatNumber(summary.scannedClans)+\' clans checked\':\'\'):recruiterReport.error||\'The first cloud recruiting scan has not published yet.\')+(failure?\' · Latest scan did not finish; showing the previous report.\':\'\');\n  if(!available)return;\n  if(model){reveal();return;}model=recruiterReport.groups?recruiterReport:legacy(recruiterReport);\n  const groups=model.groups,stats=model.stats||{};\n  const leagueChoices=[...new Map(Object.values(groups).flat().filter(r=>r.leagueTierScore).map(r=>[r.leagueTierScore,r.leagueTierName])).entries()].sort((a,b)=>a[0]-b[0]);\n  $(\'recruitment-content\').innerHTML=miniCards([[\'Available\',(groups.new?.length||0)+(groups.still?.length||0),\'recruit\'],[\'New this scan\',groups.new?.length||0,\'stars\'],[\'Joined our clan\',groups.joined_my?.length||0,\'users\'],[\'Ever joined\',stats.everJoinedMyClanCount??groups.joined_my?.length??0,\'check\']])+`${summary.baselineCreated?\'<p class="notice">The first roster baseline is saved. Later scans detect departures and verify which players are clanless.</p>\':\'\'}<div class="panel recruit-filters"><div class="section-heading"><h2>Find your next clanmate</h2><button id="recruit-reset" class="text-button">Reset filters</button></div><div class="growth-controls"><label class="recruit-search">Search<input id="recruit-search" type="search" placeholder="Player, tag or former clan"></label><label>Status<select id="recruit-section"><option value="all">All statuses</option>${sections.map(([key,label])=>`<option value="${key}">${label}</option>`).join(\'\')}</select></label><label>Minimum Town Hall<input id="recruit-hall" type="number" min="0" max="99" value="0"></label><label>Minimum war stars<input id="recruit-stars" type="number" min="0" value="0"></label><label>Minimum league<select id="recruit-league"><option value="0">Any league</option>${leagueChoices.map(([score,label])=>`<option value="${Number(score)}">${esc(label)}+</option>`).join(\'\')}</select></label><label>Sort by<select id="recruit-sort"><option value="newest">Newest departure</option><option value="window">Tightest leave window</option><option value="hall">Highest Town Hall</option><option value="stars">Most war stars</option><option value="best">Best trophies</option></select></label></div></div><p id="recruitment-count" class="small muted" aria-live="polite"></p><div id="recruitment-results"></div>${turnover()}<p class="notice">Availability was verified at the saved scan time. Check each profile before inviting. A departure window shows the time between successful scans, rather than an exact leave time. A U.S. clan listing does not confirm a player’s location or language.</p>`;\n  for(const key of [\'search\',\'section\',\'hall\',\'stars\',\'league\',\'sort\'])$(\'recruit-\'+key).oninput=()=>{filters[key]=[\'hall\',\'stars\',\'league\'].includes(key)?Math.max(0,Number($(\'recruit-\'+key).value)||0):$(\'recruit-\'+key).value;renderResults();};\n  for(const[key,value]of Object.entries(filters))$(\'recruit-\'+key).value=value;\n  $(\'recruit-reset\').onclick=()=>{filters={search:\'\',section:\'all\',hall:0,stars:0,league:0,sort:\'newest\'};for(const[key,value]of Object.entries(filters))$(\'recruit-\'+key).value=value;renderResults();};renderResults();\n }\n return {open,matches,candidate,invalidate(){model=null;}};\n})();\nfunction openRecruiter(){RecruitmentDashboard.open();}\n'
RECRUITMENT_CSS = ".player-name-with-hall{display:inline-flex;align-items:center;gap:8px;min-width:0;vertical-align:middle}.player-name-with-hall>span{overflow-wrap:anywhere}.townhall-icon{display:inline-flex;position:relative;flex:none;width:37px;height:37px;align-items:center;justify-content:center}.townhall-icon img{width:100%;height:100%;object-fit:contain;filter:drop-shadow(0 2px 2px #0005)}.compact-roster .townhall-icon{width:30px;height:30px}.recruiter-summary .section-heading{margin-bottom:5px}.recruiter-summary .recruit-summary-actions{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:12px}.recruit-summary-actions p{margin:0;max-width:580px}.recruit-summary-actions button{font-size:12px}.recruit-filters{margin-top:20px}.recruit-filters .growth-controls{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.recruit-filters input,.recruit-filters select{width:100%;min-width:0}.recruit-search{grid-column:span 2}.recruit-section{margin:28px 0}.recruit-section>summary{display:flex;align-items:center;justify-content:space-between;cursor:pointer;font-size:18px;font-weight:600;min-height:48px;border-bottom:1px solid var(--line);padding-bottom:12px;margin-bottom:15px}.recruit-section>summary::before{content:'›';margin-right:10px;color:var(--gold)}.recruit-section[open]>summary::before{content:'⌄'}.recruit-section>summary .pill{margin-left:auto}.recruit-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;align-items:start}.recruit-card{padding:20px;margin:0;min-width:0;opacity:1;transform:translateY(0);transition:opacity .38s ease var(--recruit-delay,0ms),transform .38s ease var(--recruit-delay,0ms)}.recruit-scroll-pending{opacity:0;transform:translateY(18px)}.recruit-identity{display:flex;align-items:flex-start;justify-content:space-between;gap:12px}.recruit-identity h3{font-size:17px;line-height:1.3;margin:0 0 8px}.recruit-identity>.pill{font-size:10px;flex:none}.recruit-available{color:#96e6b4;border-color:#38835a;background:#173f31}.recruit-badges{display:flex;flex-wrap:wrap;gap:6px;margin:16px 0}.recruit-badges>span{font-size:10px;border:1px solid var(--line);border-radius:7px;color:var(--muted);padding:4px 7px}.recruit-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;padding:16px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}.recruit-metrics strong{display:block;font-size:20px;font-variant-numeric:tabular-nums}.recruit-metrics small{display:block;font-size:10px;color:var(--muted);margin-top:3px}.recruit-source{font-size:12px;color:var(--muted);line-height:1.7;overflow-wrap:anywhere}.recruit-source b{color:var(--ink);font-weight:500}.recruit-source .tag{font-size:10px}.recruit-history{margin-top:14px;font-size:12px;color:var(--muted)}.recruit-history summary{cursor:pointer;color:var(--ink);padding:8px 0}.recruit-history dl{margin:8px 0}.recruit-history dl>div{padding:6px 0;border-top:1px solid #2a3e5660}.recruit-history dt{font-size:10px;margin-bottom:3px}.recruit-history dd{margin:0;color:var(--ink)}.recruit-open{display:flex;align-items:center;justify-content:space-between;padding:12px 0 0;margin-top:14px;border-top:1px solid var(--line);font-size:12px;font-weight:600;color:var(--gold);text-decoration:none}.recruit-open .icon{width:15px;height:15px}.recruit-turnover>summary{cursor:pointer;display:flex;justify-content:space-between;gap:12px;min-height:32px}.recruit-turnover .table-wrap{margin-top:15px;overflow-x:auto}.recruit-turnover table{min-width:560px}.recruit-empty{grid-column:1/-1;padding:12px 0}.recruit-card:focus-within{border-color:var(--gold)}\n@media(min-width:1250px){.recruit-grid{grid-template-columns:repeat(3,minmax(0,1fr))}.recruit-filters .growth-controls{grid-template-columns:repeat(4,minmax(0,1fr))}}\n@media(max-width:640px){.recruit-grid{grid-template-columns:minmax(0,1fr)}.recruit-filters .growth-controls{grid-template-columns:repeat(2,minmax(0,1fr))}.recruit-card{padding:18px}.recruit-summary-actions button{width:100%}.recruit-metrics strong{font-size:20px}.recruit-identity h3{font-size:17px}}\n@media(prefers-reduced-motion:reduce){.recruit-card{transition:none;transform:none;opacity:1}.recruit-scroll-pending{transform:none;opacity:1}}\n"
TOWN_HALL_IMAGES = {'1': 'data:image/webp;base64,', '2': 'data:image/webp;base64,', '3': 'data:image/webp;base64,', '4': 'data:image/webp;base64,', '5': 'data:image/webp;base64,', '6': 'data:image/webp;base64,', '7': 'data:image/webp;base64,', '8': 'data:image/webp;base64,', '9': 'data:image/webp;base64,', '10': 'data:image/webp;base64,', '11': 'data:image/webp;base64,', '12': 'data:image/webp;base64,', '13': 'data:image/webp;base64,', '14': 'data:image/webp;base64,', '15': 'data:image/webp;base64,', '16': 'data:image/webp;base64,', '17': 'data:image/webp;base64,', '18': 'data:image/webp;base64,'}

SHARED_DASHBOARD_JS = 'const SharedDashboardSync=(()=>{\n const config=data.sharedActions,enabled=Boolean(config?.enabled&&window.warHavenSession?.proof);\n const pending=new Map(),versions=new Map(),recordIds=new Map();\n const pendingStorage=\'war-haven-pending-shared:\'+data.clanTag;\n if(enabled)try{for(const[token,entry]of JSON.parse(localStorage.getItem(pendingStorage)||\'[]\'))if([\'notes\',\'lineupPlans\'].includes(entry.category)&&typeof entry.key===\'string\'&&entry.value)pending.set(token,entry);}catch{}\n function keepDrafts(){try{localStorage.setItem(pendingStorage,JSON.stringify([...pending]));}catch{status(\'Browser storage is unavailable. Keep this page open until sharing finishes.\');}}\n\n const encoder=new TextEncoder(),decoder=new TextDecoder(\'utf-8\',{fatal:true});\n const decode=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));\n const encode=value=>{let text=\'\';for(let i=0;i<value.length;i+=8192)text+=String.fromCharCode(...value.subarray(i,i+8192));return btoa(text);};\n const combine=(...parts)=>{const result=new Uint8Array(parts.reduce((n,p)=>n+p.length,0));let at=0;for(const p of parts){result.set(p,at);at+=p.length;}return result;};\n const context=encoder.encode(\'WarHavenSharedEdit:v1\');\n let keys=null,proof=null,proofUntil=0,loading=null,flushing=false,saveTimer=null,refreshKind=\'clan\',refreshTimer=null;\n const requests=new Map(),completedRequests=new Set();\n let lastStatusCheck=0;\n async function cryptoKeys(){\n  if(keys)return keys;const raw=decode(config.encryptionKey);if(raw.length!==64)throw Error(\'Shared editing configuration needs to be refreshed.\');\n  keys={enc:await crypto.subtle.importKey(\'raw\',raw.slice(0,32),\'AES-CBC\',false,[\'encrypt\',\'decrypt\']),mac:await crypto.subtle.importKey(\'raw\',raw.slice(32),{name:\'HMAC\',hash:\'SHA-256\'},false,[\'sign\',\'verify\'])};raw.fill(0);return keys;\n }\n async function identifier(category,key){const k=await cryptoKeys();return Array.from(new Uint8Array(await crypto.subtle.sign(\'HMAC\',k.mac,encoder.encode(category+\':\'+key))),b=>b.toString(16).padStart(2,\'0\')).join(\'\');}\n async function encrypt(value){const k=await cryptoKeys(),iv=crypto.getRandomValues(new Uint8Array(16)),cipher=new Uint8Array(await crypto.subtle.encrypt({name:\'AES-CBC\',iv},k.enc,encoder.encode(JSON.stringify(value)))),tag=new Uint8Array(await crypto.subtle.sign(\'HMAC\',k.mac,combine(context,iv,cipher)));return {version:1,iv:encode(iv),ciphertext:encode(cipher),tag:encode(tag)};}\n async function decrypt(envelope){\n  const k=await cryptoKeys(),iv=decode(envelope.iv),cipher=decode(envelope.ciphertext),tag=decode(envelope.tag);\n  if(envelope.version!==1||iv.length!==16||tag.length!==32||cipher.length>24000||!await crypto.subtle.verify(\'HMAC\',k.mac,tag,combine(context,iv,cipher)))throw Error(\'A shared change could not be verified. Your local changes are retained.\');\n  const value=JSON.parse(decoder.decode(await crypto.subtle.decrypt({name:\'AES-CBC\',iv},k.enc,cipher)));\n  if(![\'notes\',\'lineupPlans\'].includes(value.category)||typeof value.key!==\'string\'||!value.value||typeof value.value!==\'object\')throw Error(\'Invalid shared change.\');\n  return value;\n }\n async function api(path,body={},retry=true){\n  if(!proof||Date.now()>=proofUntil){\n   const challengeResponse=await fetch(config.url+\'/v1/challenge\',{method:\'POST\',headers:{\'Content-Type\':\'application/json\'},body:\'{}\',cache:\'no-store\'});\n   if(!challengeResponse.ok)throw Error(\'Shared saving is temporarily unavailable.\');\n   const challenge=await challengeResponse.json();proof=await window.warHavenSession.proof(challenge.salt,challenge.rounds);proofUntil=Date.now()+60000;\n  }\n  const response=await fetch(config.url+path,{method:\'POST\',headers:{\'Content-Type\':\'application/json\',\'X-War-Haven-Proof\':proof},body:JSON.stringify(body),cache:\'no-store\'});\n  const result=await response.json();\n  if(response.status===401&&retry){proof=null;return api(path,body,false);}\n  if(!response.ok){const error=Error(response.status===401?\'Reload and unlock the current dashboard to restore shared access.\':result.error||\'Shared saving is temporarily unavailable.\');error.status=response.status;error.result=result;throw error;}\n  return result;\n }\n function status(message){const el=$(\'shared-save-status\');if(el)el.querySelector(\'[data-shared-message]\').textContent=message;}\n function conflictControls(){const found=[...pending.values()].some(p=>p.conflict);$(\'shared-use-latest\').hidden=!found;$(\'shared-keep-draft\').hidden=!found;}\n function accept(record,clear){\n  const token=clear.category+\':\'+clear.key;versions.set(record.id,record.revision);recordIds.set(token,record.id);\n  const draft=pending.get(token);\n  if(draft?.migration&&JSON.stringify({...draft.value,updatedAt:null})===JSON.stringify({...clear.value,updatedAt:null})){pending.delete(token);keepDrafts();}\n  if(pending.has(token))return;\n  edits[clear.category]||={};edits[clear.category][clear.key]={...clear.value,updatedAt:record.updatedAt};persist();\n  if(clear.category===\'notes\'&&selectedTag===clear.key&&$(\'player-dialog\').open&&$(\'player-notes\').value!==(clear.value.text||\'\'))$(\'player-notes\').value=clear.value.text||\'\';\n  if(clear.category===\'lineupPlans\'&&document.body.dataset.page===\'planner\'){lineupLoaded=\'\';lineupSelection=null;renderWarPlanner();}\n }\n async function load(){\n  if(loading)return loading;\n  loading=(async()=>{const result=await api(\'/v1/records\');for(const record of result.records||[]){const clear=await decrypt(record.envelope);if(record.id!==await identifier(clear.category,clear.key))throw Error(\'A shared record failed identity verification.\');accept(record,clear);}if(!pending.size)status(\'Shared notes and plans are up to date.\');})().finally(()=>loading=null);\n  return loading;\n }\n function changed(category,key,value){\n  if(!enabled)return;\n  const token=category+\':\'+key;\n  const previous=pending.get(token),id=recordIds.get(token);\n  pending.set(token,{category,key,value:JSON.parse(JSON.stringify(value)),baseRevision:previous?previous.baseRevision:(versions.get(id)||null),operationId:crypto.randomUUID()});keepDrafts();\n  status(\'Saving shared changes…\');clearTimeout(saveTimer);saveTimer=setTimeout(flush,700);\n }\n async function flush(){\n  if(flushing||!enabled)return;flushing=true;\n  try{\n   await load();\n   for(const [token,entry]of pending){\n    if(entry.conflict)continue;\n    const id=recordIds.get(token)||await identifier(entry.category,entry.key);recordIds.set(token,id);\n    entry.envelope||=await encrypt({category:entry.category,key:entry.key,value:entry.value});\n    try{\n     const result=await api(\'/v1/record\',{id,kind:entry.category,operationId:entry.operationId,expectedRevision:entry.baseRevision||null,envelope:entry.envelope});\n     versions.set(id,result.record.revision);\n     if(pending.get(token)===entry){pending.delete(token);edits[entry.category][entry.key].updatedAt=result.record.updatedAt;persist();}else if(pending.get(token)?.baseRevision===entry.baseRevision)pending.get(token).baseRevision=result.record.revision;keepDrafts();\n    }catch(error){\n     if(error.status===409){entry.conflict=true;entry.remote=error.result.record;keepDrafts();status(\'Another leader saved a change to the same item. Your draft is kept.\');conflictControls();}\n     else throw error;\n    }\n   }\n   if(!pending.size)status(\'Shared changes saved.\');\n  }catch(error){status(error.message+\' Your draft is saved on this device.\');}\n  finally{flushing=false;if([...pending.values()].some(p=>!p.conflict)){clearTimeout(saveTimer);saveTimer=setTimeout(flush,5000);}}\n }\n function seedDrafts(){\n  for(const category of [\'notes\',\'lineupPlans\'])for(const[key,value]of Object.entries(edits[category]||{})){\n   if(!pending.has(category+\':\'+key)&&JSON.stringify(value)!==JSON.stringify(data.edits?.[category]?.[key])){changed(category,key,value);pending.get(category+\':\'+key).migration=true;keepDrafts();}\n  }\n }\n function lineupChanged(){\n  if(!enabled||!lineupSelection)return;\n  const mode=lineupOptions.mode,value={options:{...lineupOptions},tags:[...lineupSelection],updatedAt:new Date().toISOString()};\n  edits.lineupPlans||={};edits.lineupPlans[mode]=value;persist();changed(\'lineupPlans\',mode,value);\n }\n function mergeSnapshotEdits(incoming){\n  const merged=WarTracker.mergeEdits(incoming,edits);\n  for(const entry of pending.values()){merged[entry.category]||={};merged[entry.category][entry.key]=JSON.parse(JSON.stringify(entry.value));}\n  return merged;\n }\n function setBusy(kind,request){\n  const button=$(kind===\'clan\'?\'refresh-data\':\'refresh-recruiter\');if(!button)return;\n  const busy=Boolean(request&&[\'pending\',\'running\'].includes(request.status));\n  button.classList.toggle(\'is-refreshing\',busy);button.setAttribute(\'aria-busy\',String(busy));\n  const label=button.querySelector(\'[data-refresh-label]\');\n  if(label)label.textContent=busy?(request.status===\'pending\'?\'Update queued\':\'Refreshing…\'):(kind===\'clan\'?\'Refresh data\':\'Refresh recruiting candidates\');\n }\n function snapshotContains(request,kind){\n  if(!request?.startedAt)return true;\n  const captured=kind===\'clan\'?data.lastSuccessfulSync:recruiterReport.updatedAt;\n  return (Date.parse(captured)||0)>=(Date.parse(request.startedAt)||0);\n }\n function updateProgress(request){\n  const progress=$(\'shared-update-bar\'),label=$(\'shared-update-label\'),estimate=$(\'shared-update-estimate\');\n  if(!request){progress.value=0;label.textContent=\'Ready to start\';estimate.textContent=\'\';return;}\n  const active=request.status===\'running\',queued=request.status===\'pending\',elapsed=active?Math.max(0,(Date.now()-Date.parse(request.startedAt))/1000):0,duration=request.estimateSeconds||120;\n  const percent=request.status===\'completed\'?100:queued?0:Math.min(95,Math.max(request.progress||0,Math.round(5+85*Math.min(1,elapsed/duration))));\n  progress.value=percent;label.textContent=percent+\'% · \'+({pending:\'Waiting to start\',starting:\'Starting\',collecting:\'Collecting data\',publishing:\'Saving encrypted data\',deploying:\'Publishing website\',completed:\'Complete\',failed:\'Update failed\'}[request.phase||request.status]||\'Updating\');\n  const minutes=seconds=>Math.max(1,Math.ceil(seconds/60))+\' min\';\n  estimate.textContent=queued?\'Usually starts within 5 minutes, then about \'+minutes(duration)+\'. Cloud scheduling can take longer.\':active?(elapsed<duration?\'Estimated \'+minutes(duration-elapsed)+\' remaining.\':\'Taking longer than estimated. The update is still running.\'):request.status===\'completed\'?\'Complete. New data appears automatically while this dashboard stays open.\':\'Your previous dashboard is still available.\';\n }\n async function refreshStatus(kind=refreshKind){\n  try{const request=(await api(\'/v1/refresh/status\',{kind})).request;if(request)requests.set(kind,request);else requests.delete(kind);\n   setBusy(kind,request);\n   if(kind===refreshKind){updateProgress(request);$(\'website-update-submit\').disabled=Boolean(request&&[\'pending\',\'running\'].includes(request.status));}\n   const completedKey=kind+\':\'+request?.id;\n   if(request?.status===\'completed\'&&!completedRequests.has(completedKey)){\n    await checkPublishedUpdate({force:true});\n    if(snapshotContains(request,kind))completedRequests.add(completedKey);\n   }\n  }catch(error){if(kind===refreshKind)$(\'website-update-error\').textContent=error.message;}\n }\n function showRefresh(kind=\'clan\'){\n  refreshKind=kind;const recruitment=kind===\'recruitment\';\n  $(\'refresh-title\').textContent=recruitment?\'Refresh recruitment\':\'Update clan dashboard\';\n  $(\'shared-update-description\').textContent=recruitment?\'Scan tracked clans and verify recruiting candidates. This does not refresh clan wars, members or Capital data.\':\'Collect clan, war, member and Capital data. This does not scan recruiting candidates.\';\n  $(\'website-update-submit\').textContent=recruitment?\'Start recruitment scan\':\'Start clan update\';\n  $(\'website-update-error\').textContent=\'\';$(\'website-update-submit\').disabled=false;updateProgress(requests.get(kind));\n  $(\'refresh-snapshot\').textContent=\'Last successful \'+(recruitment?\'recruitment scan: \'+date(recruiterReport.updatedAt):\'clan snapshot: \'+date(data.lastSuccessfulSync));\n  $(\'automated-refresh-status\').textContent=\'After your request is accepted, you can leave or exit the browser. The update continues in the cloud.\';\n  refreshStatus(kind);if(!$(\'refresh-dialog\').open)$(\'refresh-dialog\').showModal();\n }\n function wireRefresh(){\n  const form=$(\'website-update-form\');\n  form.innerHTML=\'<p id="shared-update-description" class="small muted"></p><p class="notice">Once your request is accepted, you can close this window, leave the page or exit the browser. The update continues in the cloud. If you keep this dashboard open, new data appears automatically without signing you out.</p><button id="website-update-submit" class="primary full-width" type="submit">Start clan update</button><div class="shared-update-meter"><div id="shared-update-label" role="status">Ready to start</div><progress id="shared-update-bar" value="0" max="100" aria-label="Estimated update progress"></progress><p id="shared-update-estimate" class="small muted"></p></div>\';\n  form.onsubmit=async event=>{event.preventDefault();const kind=refreshKind;$(\'website-update-error\').textContent=\'\';$(\'website-update-submit\').disabled=true;try{const result=await api(\'/v1/refresh/request\',{kind});requests.set(kind,result.request);setBusy(kind,result.request);if(kind===refreshKind)updateProgress(result.request);}catch(error){$(\'website-update-error\').textContent=error.message;$(\'website-update-submit\').disabled=false;}};\n  $(\'refresh-data\').onclick=()=>showRefresh(\'clan\');$(\'refresh-recruiter\').onclick=()=>showRefresh(\'recruitment\');$(\'settings-refresh\').onclick=()=>{$(\'settings-dialog\').close();showRefresh(\'clan\');};\n  // These controls supersede the owner-token flow after the shared service is available.\n  $(\'refresh-dialog\').querySelectorAll(\'[data-legacy-update]\').forEach(node=>node.hidden=true);\n  $(\'howto-refresh\').textContent=\'Use Update dashboard for clan, war, member and Capital data. Use Management → Recruiter → Refresh recruiting candidates for recruitment only. Each runs independently. The estimate includes a cloud queue and a running progress bar; 100% means publication is confirmed. You can leave or exit after the request is accepted. If the dashboard stays open, the new data appears automatically and you stay unlocked.\';\n  const poll=()=>{\n   if(document.hidden)return;\n   const active=[...requests.values()].some(request=>[\'pending\',\'running\'].includes(request.status));\n   if(!$(\'refresh-dialog\').open&&!active&&Date.now()-lastStatusCheck<15000)return;\n   lastStatusCheck=Date.now();refreshStatus(\'clan\');refreshStatus(\'recruitment\');\n  };\n  clearInterval(refreshTimer);refreshTimer=setInterval(poll,5000);poll();\n }\n async function start(){\n  if(!enabled)return;\n  const banner=document.createElement(\'div\');banner.id=\'shared-save-status\';banner.className=\'notice\';banner.setAttribute(\'role\',\'status\');banner.innerHTML=\'<span data-shared-message>Loading shared notes and plans…</span> <button id="shared-use-latest" hidden>Load their change</button> <button id="shared-keep-draft" hidden>Save my draft</button>\';\n  $(\'overview\').parentElement.prepend(banner);\n  $(\'howto-saving\').textContent=\'Notes and lineup plans save automatically for every leader using this dashboard. Wait for Shared changes saved before closing. If two leaders edit the same item, your draft is kept and you can load their change or save yours. Offline drafts stay on this device and retry when connected. Other edits and captured history can still be exported with Management → Save changes / backup.\';\n  $(\'shared-storage-info\').textContent=\'Notes and lineup plans save automatically and sync between leaders. Other edits remain in this browser until backed up and imported.\';\n  $(\'shared-use-latest\').onclick=async()=>{const found=[...pending].find(([,v])=>v.conflict);if(!found)return;const[token,entry]=found;pending.delete(token);keepDrafts();if(entry.remote)accept(entry.remote,await decrypt(entry.remote.envelope));conflictControls();status(\'Loaded the other leader’s saved change.\');};\n  $(\'shared-keep-draft\').onclick=()=>{const entry=[...pending.values()].find(v=>v.conflict);if(!entry)return;if(entry.remote){versions.set(entry.remote.id,entry.remote.revision);entry.baseRevision=entry.remote.revision;}entry.conflict=false;entry.remote=null;entry.operationId=crypto.randomUUID();keepDrafts();conflictControls();flush();};\n  document.addEventListener(\'input\',event=>{if(event.target.id!==\'player-notes\'||!selectedTag)return;const value={text:event.target.value.slice(0,6000),updatedAt:new Date().toISOString()};edits.notes[selectedTag]=value;persist();changed(\'notes\',selectedTag,value);});\n  document.addEventListener(\'change\',event=>{if(event.target.matches(\'[data-lineup-player],#planner-mode,#planner-size,#planner-balance,#planner-unknown\'))lineupChanged();});\n  document.addEventListener(\'click\',event=>{const button=event.target.closest(\'button\');if(!button)return;if([\'planner-suggest\',\'planner-save\'].includes(button.id))lineupChanged();if(button.id===\'save-note\'&&selectedTag&&edits.notes[selectedTag])changed(\'notes\',selectedTag,edits.notes[selectedTag]);});\n  window.addEventListener(\'online\',flush);\n  seedDrafts();wireRefresh();\n  try{await load();conflictControls();for(const category of [\'notes\',\'lineupPlans\'])for(const [key,value]of Object.entries(edits[category]||{}))if(!recordIds.has(category+\':\'+key)&&!pending.has(category+\':\'+key))changed(category,key,value);}\n  catch(error){status(error.message+\' Local notes remain available.\');}\n  setInterval(()=>{if(!document.hidden)load().catch(error=>status(error.message));if(pending.size)flush();},20000);\n }\n return {start,changed,mergeSnapshotEdits};\n})();\n'

LIVE_DASHBOARD_JS = "const DashboardLiveUpdates=(()=>{\n let etag=null,checking=null,latestToken=window.warHavenEnvelope?.tag||null;\n const pendingEdits=incoming=>typeof SharedDashboardSync!=='undefined'?SharedDashboardSync.mergeSnapshotEdits(incoming):WarTracker.mergeEdits(incoming,edits);\n function notice(message){const banner=$('publication-update');if(!banner)return;banner.hidden=!message;if(message)$('publication-message').textContent=message;}\n function captureView(){\n  const controls=[];\n  document.querySelectorAll('input[id],select[id],textarea[id]').forEach(el=>{\n   if(['password','file','hidden'].includes(el.type)||el.id==='player-notes')return;\n   controls.push({id:el.id,value:el.value,checked:el.checked,type:el.type});\n  });\n  const active=document.activeElement;\n  return {controls,page:document.body.dataset.page,player:$('player-dialog')?.open?selectedTag:null,\n   focus:active?.id,start:active?.selectionStart,end:active?.selectionEnd,\n   x:window.scrollX||0,y:window.scrollY||0,\n   dialogs:[...document.querySelectorAll('dialog[open]')].map(el=>({id:el.id,top:el.scrollTop,left:el.scrollLeft}))};\n }\n function restoreView(view){\n  for(const saved of view.controls){\n   const el=$(saved.id);if(!el)continue;\n   if(el.tagName==='SELECT'&&![...el.options].some(option=>option.value===saved.value))continue;\n   const changed=el.value!==saved.value||el.checked!==saved.checked;\n   el.value=saved.value;if(['checkbox','radio'].includes(saved.type))el.checked=saved.checked;\n   // Reapply a rebuilt filter without dispatching the shared editing listeners.\n   if(changed){const callback=el.tagName==='SELECT'||saved.type==='checkbox'?el.onchange:el.oninput;if(typeof callback==='function')callback({target:el});}\n  }\n  const focus=$(view.focus);if(focus){focus.focus({preventScroll:true});if(view.start!=null)try{focus.setSelectionRange(view.start,view.end);}catch{}}\n  const restore=()=>{for(const saved of view.dialogs){const el=$(saved.id);if(el){el.scrollTop=saved.top;el.scrollLeft=saved.left;}}window.scrollTo?.({left:view.x,top:view.y,behavior:'instant'});};\n  restore();if(typeof requestAnimationFrame==='function')requestAnimationFrame(restore);\n }\n function applySnapshot(snapshot,report){\n  if(snapshot.schemaVersion!==1||WarTracker.tag(snapshot.clanTag)!==WarTracker.tag(data.clanTag)||!Array.isArray(snapshot.roster)||!Array.isArray(snapshot.wars))throw Error('The new snapshot could not be verified. Your current dashboard is still available.');\n  if(data.sharedActions?.encryptionKey&&snapshot.sharedActions?.encryptionKey!==data.sharedActions.encryptionKey)throw Error('Shared access settings changed. Reopen the dashboard when convenient to use the new settings.');\n  const view=captureView(),prior={data,edits,report:recruiterReport};\n  // Start with the publication so current metadata wins while saved history is retained.\n  const combined=WarTracker.mergeData(snapshot,data),nextEdits=pendingEdits(snapshot.edits||{});\n  try{\n   data={...snapshot,...combined,edits:snapshot.edits,automaticUpdates:snapshot.automaticUpdates,\n    recruiterSummary:snapshot.recruiterSummary,recruiterStatus:snapshot.recruiterStatus,sharedActions:snapshot.sharedActions};\n   edits=nextEdits;recruiterReport=report||{};\n   RecruitmentDashboard.invalidate();render();\n   if(view.page==='recruiter')openRecruiter();\n   if(view.player&&rows.some(player=>player.tag===view.player))openPlayer(view.player);\n   restoreView(view);persist();\n  }catch(error){data=prior.data;edits=prior.edits;recruiterReport=prior.report;RecruitmentDashboard.invalidate();try{render();if(view.page==='recruiter')openRecruiter();if(view.player)openPlayer(view.player);restoreView(view);}catch{}throw error;}\n }\n async function readPublication(){\n  const url=new URL(location.href);url.hash='';url.searchParams.set('_snapshot',Date.now());\n  const response=await fetch(url.href,{cache:'no-store',credentials:'omit',signal:AbortSignal.timeout(30000)});\n  if(!response.ok)throw Error('Could not load the latest snapshot. It will retry automatically.');\n  const documentHTML=new DOMParser().parseFromString(await response.text(),'text/html');\n  const payloadNode=documentHTML.getElementById('protected-payload');\n  if(!payloadNode)throw Error('The published update could not be verified. Your current dashboard remains open.');\n  const payload=JSON.parse(payloadNode.textContent);\n  const nextEtag=response.headers.get('etag')||response.headers.get('last-modified');\n  if(payload.tag===latestToken){etag=nextEtag||etag;return false;}\n  const clear=await window.warHavenSession.decrypt(payload),parsed=new DOMParser().parseFromString(clear,'text/html');\n  const source=parsed.getElementById('war-data'),report=parsed.getElementById('recruiter-data');\n  if(!source)throw Error('The published update is missing its snapshot. Your current dashboard remains open.');\n  applySnapshot(JSON.parse(source.textContent),report?JSON.parse(report.textContent):{});\n  latestToken=payload.tag;window.warHavenEnvelope=payload;etag=nextEtag||etag;\n  return true;\n }\n async function check({force=false}={}){\n  if(checking)return checking;\n  if(!/^https?:$/.test(location.protocol)||document.hidden||!window.warHavenSession?.decrypt)return false;\n  checking=(async()=>{\n   try{\n    if(!force&&etag){\n     const head=await fetch(location.href.split('#')[0],{method:'HEAD',cache:'no-store',credentials:'omit',signal:AbortSignal.timeout(15000)});\n     if(!head.ok)throw Error('Could not check the latest snapshot. It will retry automatically.');\n     const current=head.headers.get('etag')||head.headers.get('last-modified');\n     if(current&&current===etag){notice('');return false;}\n    }\n    const changed=await readPublication();notice('');if(changed)toast('Dashboard updated automatically.');return changed;\n   }catch(error){notice(error.message||'The latest data will load automatically when the connection returns.');return false;}\n  })().finally(()=>checking=null);\n  return checking;\n }\n return {check,applySnapshot};\n})();\n"

MEMBER_ACCOUNTS_JS = 'const MemberAccounts=(()=>{\n const base=\'https://war-haven-actions.readydrake18.chatgpt.site\';let proof=null,until=0,busy=false;\n async function call(path,body={},retry=true){\n  if(!proof||Date.now()>until){const r=await fetch(base+\'/v1/challenge\',{method:\'POST\',headers:{\'Content-Type\':\'application/json\'},body:\'{}\',cache:\'no-store\'});if(!r.ok)throw Error(\'Account approvals are temporarily unavailable.\');const challenge=await r.json();proof=await window.warHavenSession.proof(challenge.salt,challenge.rounds);until=Date.now()+60000;}\n  const r=await fetch(base+\'/members/api/admin/\'+path,{method:\'POST\',headers:{\'Content-Type\':\'application/json\',\'X-War-Haven-Proof\':proof},body:JSON.stringify(body),cache:\'no-store\'}),value=await r.json();\n  if(r.status===401&&retry){proof=null;return call(path,body,false);}if(!r.ok)throw Error(value.error||\'Account approvals are temporarily unavailable.\');return value;\n }\n async function open(){\n  const host=$(\'account-approvals\');if(!host||busy)return;busy=true;\n  const drafts={notes:[...host.querySelectorAll(\'[data-account-note]\')].map(node=>[node.dataset.accountNote,node.value]),title:$(\'member-news-title\')?.value||\'\',body:$(\'member-news-body\')?.value||\'\'};\n  try{\n   const result=await call(\'list\'),pending=result.accounts.filter(a=>a.status===\'pending\'||a.status===\'suspended\');\n   const badge=$(\'account-approval-count\');if(badge)badge.textContent=pending.length;\n   host.innerHTML=`<div class="panel"><div class="eyebrow">Member accounts</div><h2>Review village ownership</h2><p>Confirm that each applicant controls the village shown. Approval opens their personal dashboard immediately with the latest saved clan data.</p><p class="notice">Email delivery: ${result.emailReady?\'configured\':\'owner setup required before registration opens\'}. Clan roster: ${esc(date(result.updatedAt))}. Member data: ${formatNumber(result.memberDataBytes)} bytes.</p><p><a class="button" href="${base}/members/" target="_blank" rel="noopener">Open member sign in</a></p></div><div class="lineup-grid">${result.accounts.map(a=>`<article class="panel"><div class="player-name-with-hall">${townHallIcon(a.player?.townHallLevel)}<h3>${esc(a.player?.name||a.player_tag)}</h3></div><p class="tag">${esc(a.player_tag)} · ${esc(a.username)}</p><div class="row"><span class="pill">${esc(a.status)}</span><span class="pill">${a.email_verified?\'Email verified\':\'Email unverified\'}</span><span class="pill">${a.inClan?\'In latest roster\':\'Awaiting roster\'}</span></div><p class="small muted">${esc(a.player?.role||\'Clan role not captured\')} · requested ${esc(date(a.created_at))}</p><div class="growth-shortcuts"><button class="primary" data-account-review="approved" data-account-id="${esc(a.id)}" ${!a.email_verified||!a.inClan?\'disabled\':\'\'}>Approve</button><button data-account-review="pending" data-account-id="${esc(a.id)}">Request confirmation</button><button data-account-review="declined" data-account-id="${esc(a.id)}">Decline</button><button data-account-review="suspended" data-account-id="${esc(a.id)}">Suspend access</button></div><label class="small">Message to this applicant<input data-account-note="${esc(a.id)}" maxlength="500" value="${esc(a.review_note||\'\')}" placeholder="Optional ownership confirmation or review message"></label><details><summary>Assign website permissions · owner authorization</summary><p class="small muted">Current website role: ${esc(a.role)}. Member approval does not grant leadership access.</p><label>Role<select data-account-role="${esc(a.id)}">${[\'member\',\'co_leader\',\'leader\',\'owner\'].map(role=>`<option value="${role}" ${role===a.role?\'selected\':\'\'}>${esc(role.replace(\'_\',\' \'))}</option>`).join(\'\')}</select></label><label>GitHub owner token<input type="password" data-owner-token="${esc(a.id)}" autocomplete="off" placeholder="Owner authorization for this change only"></label><button data-account-permissions="${esc(a.id)}">Assign permissions</button></details></article>`).join(\'\')||\'<div class="panel"><h3>No applications yet</h3><p class="small muted">Verified registrations will appear here for leader or co-leader review.</p></div>\'}</div><div class="panel"><h2>Clan announcements</h2><form id="member-news-form"><label>Title<input id="member-news-title" maxlength="100" required></label><label>Message<textarea id="member-news-body" maxlength="3000" required></textarea></label><button class="primary" type="submit">Publish to member dashboards</button></form></div>`;\n   for(const[id,value]of drafts.notes){const input=host.querySelector(`[data-account-note="${id}"]`);if(input)input.value=value;}$(\'member-news-title\').value=drafts.title;$(\'member-news-body\').value=drafts.body;\n   host.querySelectorAll(\'[data-account-review]\').forEach(button=>button.onclick=async()=>{const id=button.dataset.accountId,note=host.querySelector(`[data-account-note="${id}"]`).value;button.disabled=true;try{await call(\'review\',{id,status:button.dataset.accountReview,note});toast(button.dataset.accountReview===\'approved\'?\'Approved. Their dashboard is available immediately.\':\'Account review updated.\');await openAgain();}catch(error){toast(error.message);button.disabled=false;}});\n   host.querySelectorAll(\'[data-account-permissions]\').forEach(button=>button.onclick=async()=>{const id=button.dataset.accountPermissions,input=host.querySelector(`[data-owner-token="${id}"]`),ownerToken=input.value;input.value=\'\';button.disabled=true;try{await call(\'role\',{id,role:host.querySelector(`[data-account-role="${id}"]`).value,ownerToken});toast(\'Website permissions updated. That account must sign in again.\');await openAgain();}catch(error){toast(error.message);button.disabled=false;}});\n   $(\'member-news-form\').onsubmit=async event=>{event.preventDefault();try{await call(\'announcement\',{title:$(\'member-news-title\').value,body:$(\'member-news-body\').value});$(\'member-news-form\').reset();toast(\'Announcement published to member dashboards.\');}catch(error){toast(error.message);}};\n  }catch(error){host.innerHTML=`<div class="panel"><h2>Account approvals</h2><p class="notice">${esc(error.message)}</p><button id="member-approvals-retry">Try again</button></div>`;$(\'member-approvals-retry\').onclick=open;}\n  finally{busy=false;}\n }\n async function openAgain(){busy=false;await open();}\n function start(){\n  if(!window.warHavenSession?.proof)return;\n  setInterval(()=>{if(!document.hidden&&document.body.dataset.page===\'accounts\'&&!document.querySelector(\'[data-owner-token]:focus,[data-account-note]:focus,#member-news-title:focus,#member-news-body:focus\')&&![...document.querySelectorAll(\'[data-owner-token]\')].some(input=>input.value))open();},60000);\n }\n return {open,start};\n})();\n'

